export function WelcomeScreen({
  heading = "{{heading}}",
  subheading = "{{subheading}}",
  ctaLabel = "{{ctaLabel}}",
  accent = "{{accent}}",
  layout = "{{layout}}",
}) {
  const outer = {
    centered: { display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center" },
    split: { display: "flex", alignItems: "center", gap: 20, textAlign: "left" },
    minimal: { display: "flex", alignItems: "center", gap: 14, padding: "18px 22px", textAlign: "left" },
  }[layout] ?? {};
  const minimal = layout === "minimal";
  return (
    <div style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 28, width: 420, borderRadius: 16, border: "1px solid #24143018", boxSizing: "border-box", ...outer }}>
      <div aria-hidden="true" style={{ marginBottom: minimal || layout === "split" ? 0 : 16, flexShrink: 0 }}>
        <svg viewBox="0 0 64 64" width={minimal ? 36 : 56} height={minimal ? 36 : 56}>
          <circle cx="32" cy="32" r="30" fill={accent} opacity="0.25" />
          <circle cx="32" cy="26" r="12" fill={accent} />
          <rect x="16" y="42" width="32" height="14" rx="7" fill={accent} opacity="0.6" />
        </svg>
      </div>
      <div>
        <h1 style={{ margin: minimal ? "0 0 2px" : "0 0 8px", fontSize: minimal ? 16 : 22, fontWeight: 800 }}>{heading}</h1>
        {!minimal && <p style={{ margin: "0 0 18px", fontSize: 13.5, color: "#241430b3" }}>{subheading}</p>}
        <div style={{ display: "flex", alignItems: "center", gap: 14, flexDirection: layout === "centered" ? "column" : "row", marginLeft: minimal ? "auto" : 0 }}>
          <button type="button" style={{ background: accent, border: "1.5px solid " + accent, borderRadius: 9, padding: "10px 20px", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{ctaLabel}</button>
          <a href="#" style={{ fontSize: 12.5, color: "#24143090", textDecoration: "none" }}>Skip for now</a>
        </div>
      </div>
    </div>
  );
}
